delete from public.planned_sessions where cardinality(exercise_ids)=0;

on conflict (id) do update set name=excluded.name,name_en=excluded.name_en,target=excluded.target,mode=excluded.mode,equipment=excluded.equipment,gender=excluded.gender,sets=excluded.sets,reps=excluded.reps,tips=excluded.tips,images=excluded.images,video_id=excluded.video_id,source=excluded.source,license=excluded.license,needs_review=excluded.needs_review;

notify pgrst, 'reload schema';
